arguments.command:
cd /tmp/ross-main
for b in rachel monica phoebe joey chandler ross; do
  echo "=== friend/$b latest ===";
  git log origin/friend/$b -1 --format='%H %ci %s';
done

cd /tmp/ross-main
for b in rachel monica phoebe joey chandler; do
  echo "================ $b ================";
  git log origin/friend/$b --reverse --since="2026-10-23T00:24:00Z" --format='---COMMIT %H%n%ci%n%B' 2>/dev/null;
done

cd /tmp/ross-main
for sha in 508747624e5d9f2f697d7ed26ca0e2f0e0b5eac1 11d89dee74f23677705baddfdc21c814d27b33bd 7e094047a2fb8fab33d75f1d6189c97fb431b2ca a2a818aa45f6c0b16627661cc5b22c5a91450648 7cf546e7692837a7916d6c2a78be839e9fbfbbd9; do
  echo "===== $sha =====";
  git show -s --format='%ci' $sha;
  git show -s --format=%B $sha | sed -n '/^$/,$p' | tail -n +2;
done
